def transform(grid):
    R, C = len(grid), len(grid[0])
    ones = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 1]
    r0, r1 = min(r for r, c in ones), max(r for r, c in ones)
    c0, c1 = min(c for r, c in ones), max(c for r, c in ones)

    panel = [[grid[r][c] for c in range(c0, c1 + 1)]
             for r in range(r0, r1 + 1)]
    out = [list(row) for row in zip(*panel)]
    h, w = len(out), len(out[0])

    # Keep the repeated pattern color; clear the three embedded corner labels.
    counts = {}
    for row in panel:
        for v in row:
            if v not in (0, 1):
                counts[v] = counts.get(v, 0) + 1
    pattern = max(counts, key=counts.get)
    for r in range(h):
        for c in range(w):
            if out[r][c] not in (1, pattern):
                out[r][c] = 1

    marks = [(r, c, grid[r][c]) for r in range(R) for c in range(C)
             if grid[r][c] not in (0, 1)
             and not (r0 <= r <= r1 and c0 <= c <= c1)]
    if len(marks) >= 3:
        # The external three marks form an L. Its corner and endpoints map
        # to the three corresponding interior corner-label positions.
        rs = [r for r, c, v in marks]
        cs = [c for r, c, v in marks]
        mr0, mr1, mc0, mc1 = min(rs), max(rs), min(cs), max(cs)
        for r, c, v in marks:
            if r == mr0 and c == mc0:
                rr, cc = 1, 1
            elif r == mr0 and c == mc1:
                rr, cc = 1, w - 2
            else:
                rr, cc = h - 2, w - 2
            out[rr][cc] = v
    return out
